 function header(title:string,description:string,action?:ReactNode){return <div className="page-heading"><div><div className="eyebrow">YOUR SPEAKING JOURNEY</div>{isHome&&title!==content.brand.guestGreeting&&title!==content.brand.greeting.replace('{name}',name)?<h2 className="section-title">{title}</h2>:<h1>{title}</h1>}<p>{description}</p></div>{action}</div>}
