   {data.attempts.length?<div className="history-list">{data.attempts.map((a:any)=>{const q=bank.find(q=>q.id===a.question_id);return <article className="history-card" key={a.id}><div className="card-top"><span className="history-date">{dateLabel(a.created_at)} · {fmt(a.duration)}</span><Pill tone={a.status==='evaluated'?'green':'peach'}>{a.status==='evaluated'?'Feedback ready':a.status==='failed'?'Evaluation needs retry':a.status==='evaluating'?'Evaluating':'Recording saved'}</Pill></div><h3>{q?.text||a.question_id}</h3><p>{a.transcript||'No browser transcript. Your original audio is saved.'}</p>{a.audio_key?<audio controls preload="none" src={`/api/audio/${a.id}`}/>:<p className="storage-note"><Shield size={13}/>Audio was not retained. Transcript and feedback are saved.</p>}<div className="history-actions"><button className="text-link" onClick={()=>loadAttempt(a)}>View answer <ArrowRight size={14}/></button>{a.status!=='evaluated'&&<button className="text-link" disabled={busy||!data.aiConfigured} onClick={()=>retryEvaluation(a)}>Retry evaluation <RefreshCw size={14}/></button>}<button className="text-link" onClick={()=>download(`transcript-${a.id}.txt`,a.transcript)}><Download size={14}/>Transcript</button>{a.audio_key&&<a className="text-link" href={`/api/audio/${a.id}`} download><Download size={14}/>Audio</a>}<button className="text-link danger" onClick={()=>setModal(`delete:${a.id}`)}><Trash2 size={14}/>Delete</button></div></article>})}</div>:<Empty icon={AudioLines} title="Your first answer is the beginning." text="Record a speaking answer and sign in to keep your audio, original transcript and feedback together." action={<Button onClick={()=>startSession()}><Mic size={16}/>Start speaking</Button>}/>}
